const body = $json.body ?? $json;
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Tender body must be a JSON object');
const title = String(body.title ?? '').trim();
const organization = String(body.organization ?? body.organisation ?? '').trim();
const summary = String(body.summary ?? '').trim();
const deadline = body.deadline == null || body.deadline === '' ? null : String(body.deadline);
if (title.length < 4 || title.length > 100 || organization.length < 2 || organization.length > 80 || summary.length < 12 || summary.length > 700) throw new Error('Invalid tender title, organization, or summary');
if (deadline && !/^\d{4}-\d{2}-\d{2}$/.test(deadline)) throw new Error('Invalid deadline');
return [{ json: { title, source: String(body.source ?? 'manual').slice(0,40), raw_payload: { ...body, title, organization, summary, deadline }, language: String(body.language ?? 'en') } }];

const lead = $('Validate & Normalize').first().json;
const ex = $json.output ?? $json;
const raw = lead.raw_payload;
const extracted = { ...ex, title: lead.title, organization: raw.organization, organisation: raw.organization, summary: raw.summary, deadline: raw.deadline ?? null };
const title = String(lead.title).toLowerCase();
const itWords = ['software','development','web','mobile','application','digital','data','cloud','system','plateforme','developpement','numerique'];
let score = 50;
for (const word of itWords) if (title.includes(word)) score += 8;
if (Array.isArray(ex.requirements) && ex.requirements.length >= 3) score += 10;
return [{ json: { row_json: JSON.stringify({ title: lead.title, source: lead.source, raw_payload: raw, extracted, relevance_score: Math.max(0,Math.min(100,score)), deadline: raw.deadline ?? null }) } }];

const src = $json ?? {};
let leadId = '';
try { leadId = src.lead_id ?? src.id ?? ''; } catch (e) {}
const errRaw = src.error ?? src.message ?? src;
const errText = typeof errRaw === 'string' ? errRaw : (errRaw.message ?? JSON.stringify(errRaw));
return [{ json: { error_json: JSON.stringify({ lead_id: String(leadId ?? ''), error: String(errText).slice(0, 500) }) } }];

